def metric(value, unit: str, precision: int = 3) -> str:
    """Return a value with a SI prefix and unit.

    Args:
        value: Input number.
        unit: Unit string.
        precision: Number of significant digits.

    Returns:
        str: Formatted value with SI prefix and unit.
    """
    if value == 0:
        abs_val = 0
    else:
        abs_val = abs(value)

    for factor, prefix in _si_prefixes:
        if abs_val >= factor:
            scaled = value / factor
            # Compute decimal places from significant digits
            if scaled == 0:
                decimal_places = precision - 1
            else:
                abs_scaled = abs(scaled)
                if abs_scaled >= 100:
                    decimal_places = max(0, precision - 3)
                elif abs_scaled >= 10:
                    decimal_places = max(0, precision - 2)
                else:
                    decimal_places = max(0, precision - 1)
            fmt = "{:." + str(decimal_places) + "f}"
            num_str = fmt.format(scaled)
            if unit == "\u00b0":
                return num_str + unit
            else:
                return num_str + " " + prefix + unit

    # Fallback (should not reach here)
    fmt = "{:." + str(precision - 1) + "f}"
    num_str = fmt.format(value)
    if unit == "\u00b0":
        return num_str + unit
    else:
        return num_str + " " + unit

